    private static func pick(_ language: AppLanguage, _ ko: String, _ ja: String, _ de: String,
                             _ es: String, _ pt: String, _ ru: String, _ tr: String, _ vi: String) -> String? {
        switch language {
        case .korean: return ko
        case .japanese: return ja
        case .german: return de
        case .spanish: return es
        case .portuguese: return pt
        case .russian: return ru
        case .turkish: return tr
        case .vietnamese: return vi
        default: return nil
        }
    }

    private static func roadmapPick(_ language: AppLanguage, _ fr: String, _ ko: String, _ ja: String,
                                    _ de: String, _ es: String, _ pt: String, _ ru: String,
                                    _ tr: String, _ vi: String) -> String? {
        if language == .french { return fr }
        return pick(language, ko, ja, de, es, pt, ru, tr, vi)
    }
